import requests
from requests.models import Request

class MagicFile:
    def __getattr__(self, name):
        if name == 'read':
            return lambda: b'magic content'
        raise AttributeError(name)

def test_repro():
    try:
        # We simulate what happens in _encode_files
        # Passing a file-like object in the 'files' parameter of requests.post
        # Since we can't easily mock the server, we just check if it raises TypeError
        # when preparing the request.
        files = {'file': ('test.txt', MagicFile())}
        req = requests.Request('POST', 'http://httpbin.org/post', files=files)
        req.prepare()
        print("Success!")
    except TypeError as e:
        print(f"Caught expected TypeError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

